#include <stdint.h>

void vectorized_s256(int iterations, float* a, float* d, float aa[256][256], float bb[256][256])
{
    for (int nl = 0; nl < 10*(iterations/256); nl++) {
        for (int i = 0; i < 256; i++) {
            // j=1: a[1] = 1.0f - a[0]
            // j=2: a[2] = 1.0f - a[1]
            // Each iteration depends on previous a[j-1], so this is a recurrence.
            // We cannot vectorize across j due to the dependency a[j] = 1.0f - a[j-1].
            // However, we can observe:
            // a[j] = 1.0f - a[j-1]
            // a[j+1] = 1.0f - a[j] = 1.0f - (1.0f - a[j-1]) = a[j-1]
            // So even indices of a[] (starting from j=2) equal a[0],
            // and odd indices of a[] (starting from j=1) equal 1.0f - a[0].
            // We can precompute the two values and fill a[] and aa[][] accordingly.

            float a0 = a[0];
            float val_odd  = 1.0f - a0;   // a[j] for odd j
            float val_even = a0;           // a[j] for even j (j>=2)

            // Process j=1..255
            // For odd j: a[j] = val_odd, aa[j][i] = val_odd + bb[j][i]*d[j]
            // For even j: a[j] = val_even, aa[j][i] = val_even + bb[j][i]*d[j]

            // Unroll by 4 pairs (8 iterations at a time)
            int j = 1;
            for (; j + 7 < 256; j += 8) {
                // j+0: odd
                a[j+0] = val_odd;
                aa[j+0][i] = val_odd  + bb[j+0][i] * d[j+0];
                // j+1: even
                a[j+1] = val_even;
                aa[j+1][i] = val_even + bb[j+1][i] * d[j+1];
                // j+2: odd
                a[j+2] = val_odd;
                aa[j+2][i] = val_odd  + bb[j+2][i] * d[j+2];
                // j+3: even
                a[j+3] = val_even;
                aa[j+3][i] = val_even + bb[j+3][i] * d[j+3];
                // j+4: odd
                a[j+4] = val_odd;
                aa[j+4][i] = val_odd  + bb[j+4][i] * d[j+4];
                // j+5: even
                a[j+5] = val_even;
                aa[j+5][i] = val_even + bb[j+5][i] * d[j+5];
                // j+6: odd
                a[j+6] = val_odd;
                aa[j+6][i] = val_odd  + bb[j+6][i] * d[j+6];
                // j+7: even
                a[j+7] = val_even;
                aa[j+7][i] = val_even + bb[j+7][i] * d[j+7];
            }
            // Scalar tail
            for (; j < 256; j++) {
                float val = (j & 1) ? val_odd : val_even;
                a[j] = val;
                aa[j][i] = val + bb[j][i] * d[j];
            }
        }
    }
}
